module lava_game(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] start_idx,\n    input wire [3:0] goal_idx,\n    input wire [7:0] A,\n    input wire [7:0] F,\n    input wire [31:0] rows_data,\n    input wire [31:0] cols_data,\n    output reg [1:0] result,\n    output reg done\n);\n\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] BUILD_FATHER = 4'd1;\n    localparam [3:0] FW_FATHER_K = 4'd2;\n    localparam [3:0] FW_FATHER_I = 4'd3;\n    localparam [3:0] FW_FATHER_J = 4'd4;\n    localparam [3:0] SAVE_FATHER = 4'd5;\n    localparam [3:0] BUILD_ELSA = 4'd6;\n    localparam [3:0] FW_ELSA_K = 4'd7;\n    localparam [3:0] FW_ELSA_I = 4'd8;\n    localparam [3:0] FW_ELSA_J = 4'd9;\n    localparam [3:0] COMPARE = 4'd10;\n    localparam [3:0] DONE = 4'd11;\n\n    localparam [1:0] SUCCESS = 2'b00;\n    localparam [1:0] GO_FOR_IT = 2'b01;\n    localparam [1:0] NO_CHANCE = 2'b10;\n    localparam [1:0] NO_WAY = 2'b11;\n\n    reg [3:0] state, next_state;\n    reg [3:0] i_cnt, j_cnt, k_cnt;\n    reg [3:0] rows [0:7];\n    reg [3:0] cols [0:7];\n    reg [3:0] dist [0:7][0:7];\n    reg [3:0] dist_father_result;\n    reg [3:0] dist_elsa_result;\n    reg [15:0] A_sq;\n    reg [7:0] F_reg;\n    reg [3:0] N_reg;\n    reg [3:0] start_reg, goal_reg;\n\n    wire [3:0] row_i = rows[i_cnt];\n    wire [3:0] col_i = cols[i_cnt];\n    wire [3:0] row_j = rows[j_cnt];\n    wire [3:0] col_j = cols[j_cnt];\n\n    wire [3:0] row_diff = (row_i > row_j) ? (row_i - row_j) : (row_j - row_i);\n    wire [3:0] col_diff = (col_i > col_j) ? (col_i - col_j) : (col_j - col_i);\n    wire [7:0] row_diff_sq = row_diff * row_diff;\n    wire [7:0] col_diff_sq = col_diff * col_diff;\n    wire [15:0] euc_dist_sq = {8'd0, row_diff_sq} + {8'd0, col_diff_sq};\n\n    wire father_edge = ((row_i == row_j) && (col_diff <= F_reg[3:0])) || ((col_i == col_j) && (row_diff <= F_reg[3:0]));\n    wire elsas_edge = (euc_dist_sq <= A_sq);\n\n    wire [3:0] dist_ik = dist[i_cnt][k_cnt];\n    wire [3:0] dist_kj = dist[k_cnt][j_cnt];\n    wire [3:0] dist_ij = dist[i_cnt][j_cnt];\n    wire [3:0] new_dist = dist_ik + dist_kj;\n    wire update_condition = (dist_ik < 4'hF) && (dist_kj < 4'hF) && (new_dist < dist_ij);\n\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = BUILD_FATHER;\n            BUILD_FATHER: begin\n                if (i_cnt >= N_reg && j_cnt >= N_reg) next_state = FW_FATHER_K;\n                else next_state = BUILD_FATHER;\n            end\n            FW_FATHER_K: begin\n                if (k_cnt >= N_reg) next_state = SAVE_FATHER;\n                else next_state = FW_FATHER_I;\n            end\n            FW_FATHER_I: begin\n                if (i_cnt >= N_reg) next_state = FW_FATHER_K;\n                else next_state = FW_FATHER_J;\n            end\n            FW_FATHER_J: begin\n                if (j_cnt >= N_reg) next_state = FW_FATHER_I;\n                else next_state = FW_FATHER_J;\n            end\n            SAVE_FATHER: next_state = BUILD_ELSA;\n            BUILD_ELSA: begin\n                if (i_cnt >= N_reg && j_cnt >= N_reg) next_state = FW_ELSA_K;\n                else next_state = BUILD_ELSA;\n            end\n            FW_ELSA_K: begin\n                if (k_cnt >= N_reg) next_state = COMPARE;\n                else next_state = FW_ELSA_I;\n            end\n            FW_ELSA_I: begin\n                if (i_cnt >= N_reg) next_state = FW_ELSA_K;\n                else next_state = FW_ELSA_J;\n            end\n            FW_ELSA_J: begin\n                if (j_cnt >= N_reg) next_state = FW_ELSA_I;\n                else next_state = FW_ELSA_J;\n            end\n            COMPARE: next_state = DONE;\n            DONE: next_state = DONE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 2'b00;\n            i_cnt <= 4'd0;\n            j_cnt <= 4'd0;\n            k_cnt <= 4'd0;\n            dist_father_result <= 4'hF;\n            dist_elsa_result <= 4'hF;\n            A_sq <= 16'd0;\n            F_reg <= 8'd0;\n            N_reg <= 4'd0;\n            start_reg <= 4'd0;\n            goal_reg <= 4'd0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: if (start) begin\n                    N_reg <= N;\n                    start_reg <= start_idx;\n                    goal_reg <= goal_idx;\n                    F_reg <= F;\n                    rows[0] <= rows_data[3:0];\n                    rows[1] <= rows_data[7:4];\n                    rows[2] <= rows_data[11:8];\n                    rows[3] <= rows_data[15:12];\n                    rows[4] <= rows_data[19:16];\n                    rows[5] <= rows_data[23:20];\n                    rows[6] <= rows_data[27:24];\n                    rows[7] <= rows_data[31:28];\n                    cols[0] <= cols_data[3:0];\n                    cols[1] <= cols_data[7:4];\n                    cols[2] <= cols_data[11:8];\n                    cols[3] <= cols_data[15:12];\n                    cols[4] <= cols_data[19:16];\n                    cols[5] <= cols_data[23:20];\n                    cols[6] <= cols_data[27:24];\n                    cols[7] <= cols_data[31:28];\n                    i_cnt <= 4'd0;\n                    j_cnt <= 4'd0;\n                    k_cnt <= 4'd0;\n                end\n                BUILD_FATHER: begin\n                    if (i_cnt < N_reg && j_cnt < N_reg) begin\n                        if (i_cnt == j_cnt) dist[i_cnt][j_cnt] <= 4'd0;\n                        else if (father_edge) dist[i_cnt][j_cnt] <= 4'd1;\n                        else dist[i_cnt][j_cnt] <= 4'hF;\n                        if (j_cnt == N_reg - 1) begin\n                            j_cnt <= 4'd0;\n                            if (i_cnt == N_reg - 1) i_cnt <= 4'd0;\n                            else i_cnt <= i_cnt + 4'd1;\n                        end else j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n                FW_FATHER_K: begin\n                    i_cnt <= 4'd0;\n                    k_cnt <= 4'd0;\n                end\n                FW_FATHER_I: begin\n                    j_cnt <= 4'd0;\n                    if (i_cnt == N_reg - 1) i_cnt <= 4'd0;\n                    else i_cnt <= i_cnt + 4'd1;\n                end\n                FW_FATHER_J: begin\n                    if (j_cnt < N_reg) begin\n                        if (update_condition) dist[i_cnt][j_cnt] <= new_dist;\n                        j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n                SAVE_FATHER: begin\n                    dist_father_result <= dist[start_reg][goal_reg];\n                end\n                BUILD_ELSA: begin\n                    A_sq <= A * A;\n                    if (i_cnt < N_reg && j_cnt < N_reg) begin\n                        if (i_cnt == j_cnt) dist[i_cnt][j_cnt] <= 4'd0;\n                        else if (elsas_edge) dist[i_cnt][j_cnt] <= 4'd1;\n                        else dist[i_cnt][j_cnt] <= 4'hF;\n                        if (j_cnt == N_reg - 1) begin\n                            j_cnt <= 4'd0;\n                            if (i_cnt == N_reg - 1) i_cnt <= 4'd0;\n                            else i_cnt <= i_cnt + 4'd1;\n                        end else j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n                FW_ELSA_K: begin\n                    i_cnt <= 4'd0;\n                    k_cnt <= 4'd0;\n                end\n                FW_ELSA_I: begin\n                    j_cnt <= 4'd0;\n                    if (i_cnt == N_reg - 1) i_cnt <= 4'd0;\n                    else i_cnt <= i_cnt + 4'd1;\n                end\n                FW_ELSA_J: begin\n                    if (j_cnt < N_reg) begin\n                        if (update_condition) dist[i_cnt][j_cnt] <= new_dist;\n                        j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n                COMPARE: begin\n                    if (dist_father_result == 4'hF && dist_elsa_result == 4'hF) result <= NO_WAY;\n                    else if (dist_father_result == 4'hF) result <= GO_FOR_IT;\n                    else if (dist_elsa_result == 4'hF) result <= NO_CHANCE;\n                    else if (dist_elsa_result == dist_father_result) result <= SUCCESS;\n                    else if (dist_elsa_result < dist_father_result) result <= GO_FOR_IT;\n                    else result <= NO_CHANCE;\n                    done <= 1'b1;\n                end\n                DONE: begin\n                end\n            endcase\n        end\n    end\n\nendmodule